FuncDef.Code:
float opSmoothInfRepeatY(inout vec3 p, float spacing, float smoothness)
{
    float halfsize = spacing*0.5;
    float cellIndex = floor((p.y + halfsize)/spacing);

    //p.y = mod(p.y + halfsize, spacing) - halfsize;
    p.y = modEx(p.y + halfsize, spacing, smoothness) - halfsize;

    return cellIndex;
}
